// ─── Step type census (regenerated on every sync from the real data) ────────

export {
  /** Every step `type` that actually occurs in the data, most frequent first. */
  STEP_TYPES,
  /** How many times each step type occurs across all 12 courses. */
  STEP_TYPE_COUNTS,
  /** { courses, lessons, steps, distinctStepTypes } */
  CURRICULUM_STATS,
} from './stepTypes.generated';

export type { StepType } from './stepTypes.generated';

import { STEP_TYPES, type StepType } from './stepTypes.generated';
import type { LessonStep } from './types';

/**
 * Narrow `LessonStep` to one concrete variant.
 *
 *   function renderQuiz(step: StepOfType<'quiz'>) { ... }
 */
export type StepOfType<T extends StepType> = Extract<LessonStep, { type: T }>;

const STEP_TYPE_SET: ReadonlySet<string> = new Set<string>(STEP_TYPES);

/** True if `value` is a step type that occurs somewhere in the curriculum. */
export function isKnownStepType(value: string): value is StepType {
  return STEP_TYPE_SET.has(value);
}
